SELECT COUNT(DISTINCT CAST(s.playerid AS BIGINT)) AS players
FROM app.sessions s
JOIN game.bets b ON CAST(s.playerid AS BIGINT) = b.member_ref;

select count(*) as players
from (
    select distinct cast(playerid as bigint) as player_id from app.sessions
    intersect
    select distinct member_ref as player_id from game.bets
) t;
